async function o(){const s=await fetch("/api/assistants");if(s.status===401)throw new Error("UNAUTHORIZED");if(!s.ok)throw new Error("HTTP "+s.status);return s.json()}async function r(s){const t=await fetch("/api/assistants",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(s)});if(t.status===401)throw new Error("UNAUTHORIZED");if(!t.ok)throw new Error("HTTP "+t.status);return t.json()}async function a(s,t){const n=await fetch(`/api/assistants/${encodeURIComponent(s)}`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)});if(n.status===401)throw new Error("UNAUTHORIZED");if(!n.ok)throw new Error("HTTP "+n.status);return n.json()}async function e(s){const t=await fetch(`/api/assistants/${encodeURIComponent(s)}`,{method:"DELETE"});if(t.status===401)throw new Error("UNAUTHORIZED");if(!t.ok)throw new Error("HTTP "+t.status);return t.json()}export{r as c,e as d,o as f,a as u};
